using System.Collections.ObjectModel;
using WPFUI.Services;

namespace WPFUI.Models;

public abstract class LivingEntity : BaseNotificationClass
{
    private string _name = string.Empty;
    private int _currentHitPoints;
    private int _maximumHitPoints;
    private int _gold;
    private int _level;
    private GameItem? _currentWeapon;
    private GameItem? _currentConsumable;
    private Inventory _inventory;

    public string Name
    {
        get{return _name;}
        private set
        {
            _name = value;
            OnPropertyChanged();
        }
    }

    public int CurrentHitPoints
    {
        get{return _currentHitPoints;}
        private set
        {
            _currentHitPoints = value;
            OnPropertyChanged();
        }
    }

    public int MaximumHitPoints
    {
        get{return _maximumHitPoints;}
        protected set
        {
            _maximumHitPoints = value;
            OnPropertyChanged();
        }
    }

    public int Gold
    {
        get{return _gold;}
        private set
        {
            _gold = value;
            OnPropertyChanged();
        }
    }

    public int Level
    {
        get{return _level;}
        protected set
        {
            _level = value;
            OnPropertyChanged();
        }
    }
    public Inventory Inventory
    {
        get => _inventory;
        private set
        {
            _inventory = value;
            OnPropertyChanged();
        }
    }

    public GameItem? CurrentWeapon
    {
        get{return _currentWeapon;}
        set
        {
            if(_currentWeapon?.Action != null)
            {
                _currentWeapon.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentWeapon = value;
            if(_currentWeapon?.Action != null)
            {
                _currentWeapon.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }
            OnPropertyChanged();
        }
    }

    public GameItem? CurrentConsumable
    {
        get{return _currentConsumable;}
        set
        {
            if(_currentConsumable?.Action != null)
            {
                _currentConsumable.Action.OnActionPerformed -= RaiseActionPerformedEvent;
            }
            _currentConsumable = value;
            if(_currentConsumable?.Action != null)
            {
                _currentConsumable.Action.OnActionPerformed += RaiseActionPerformedEvent;
            }
            OnPropertyChanged();
        }
    }
    public bool IsDead => CurrentHitPoints <= 0;
    public event EventHandler<string>? OnActionPerformed;
    public event EventHandler? OnKilled;

    protected LivingEntity(string name, int maximumHitPoints, int currentHitPoints, int gold, int level = 1)
    {
        Name = name;
        MaximumHitPoints = maximumHitPoints;
        CurrentHitPoints = currentHitPoints;
        Gold = gold;
        Level = level;

        Inventory = new Inventory();
    }

    public void UseCurrentWeaponOn(LivingEntity target)
    {
        if(CurrentWeapon == null)
        {
            return;
        }
        CurrentWeapon.PerformAction(this, target);
    }

    public void UseCurrentConsumable()
    {
        GameItem? consumable = CurrentConsumable;
        if(consumable == null)
        {
            return;
        }
        consumable.PerformAction(this, this);
        RemoveItemFromInventory(consumable);
    }

    public void TakeDamage(int value)
    {
        CurrentHitPoints -= value;
        if (IsDead)
        {
            CurrentHitPoints = 0;
            RaiseOnKilledEvent();
        }
    }

    public void Heal(int value)
    {
        CurrentHitPoints += value;
        if(CurrentHitPoints > MaximumHitPoints)
        {
            CurrentHitPoints = MaximumHitPoints;
        }
    }

    public void CompleteHeal()
    {
        CurrentHitPoints = MaximumHitPoints;
    }

    public void ReceiveGold(int value)
    {
        Gold += value;
    }

    public void SpendGold(int value)
    {
        if(value > Gold)
        {
            throw new ArgumentOutOfRangeException($"{Name} only has {Gold} gold");
        }
        Gold -= value;
    }

    public void AddItemToInventory(GameItem item)
    {   
        Inventory = Inventory.AddItem(item);
    }

    public void RemoveItemFromInventory(GameItem item)
    {   
        Inventory = Inventory.RemoveItem(item);
    }

    public void RemoveItemsFromInventory(List<ItemQuantity> itemQuantities)
    {
        Inventory = Inventory.RemoveItems(itemQuantities);
    }
    private void RaiseOnKilledEvent()
    {
        OnKilled?.Invoke(this, new System.EventArgs());
    }

    private void RaiseActionPerformedEvent(object? sender,string result)
    {
        OnActionPerformed?.Invoke(this, result);
    }
}
